"""Assemble concise evidence, verify runtime hashes and count semantic solutions."""
import hashlib,json,pathlib,sys
sys.dont_write_bytecode=True
from witness import system
R=pathlib.Path(__file__).resolve().parents[1];E=R/'evidence'
def read(name):return json.loads((E/name).read_text())
p=read('packaging.json')
assert all(hashlib.sha256((R/name).read_bytes()).hexdigest()==digest for name,digest in p['runtime_hashes'].items())
a=read('fraction-counterexample-before.json');b=read('fraction-counterexample.json')
assert a['probe']['shortcut_correct'] and not b['probe']['shortcut_correct']
assert system(a['record']['question'][':question/problem'])==system(b['record']['question'][':question/problem'])
g=read('repair2-grader-results.json');m=read('math-results.json');v=read('rational-results.json');d=read('rational-delivery-results.json')
def semantic_count(records):return len({str(system(r['question'][':question/problem']).rref()[0]) for r in records})
semantic={'raw':semantic_count(read('rational-records.json')),'delivered':semantic_count(read('delivery-rational/accepted.json'))}
assert semantic['raw']==semantic['delivered']
report={'status':'ready_for_independent_review','runtime_version':'1.1.1','manifest':'package.json','reproduction':{'before_fraction_count':a['probe']['fraction_count'],'after_fraction_count':b['probe']['fraction_count'],'same_visible_system':True},'fidelity':{'complete_banks':14,'source_choices':70,'report':'source-replay.json'},'correctness':{'retained_math_records':m['count'],'affected_records':v['records'],'rational_records':v['rational_records'],'source_first_proposals_retained':v['ordinary_source_first_proposals_kept'],'zero_coordinate_boundary':'Checks current complete visible records, not merely metadata.'},'grading':{k:g[k] for k in ('accepted_checks','rejected_checks','documented_unresolved_checks','database_writes')},'decision_variation':{'six_default_cases':m['decision_cases_from_visible_math'],'default_semantic_solution_sets':59,'affected_distinct_solution_sets':semantic,'sole_fraction_successes':v['sole_fraction_successes'],'delivery_same_semantic_instances':d['same_semantic_instances'],'affected_delivery_duplicates':d['duplicate_count'],'controlled_all_five_roles':'role-counterfactual-results.json','conditional_probes':'rational-delivery-results.json'},'rendering':{'rational_cases':len(read('render-rational/rendering.json')['cases']),'zero_boundary_cases':len(read('render-zero-boundaries/rendering.json')['cases']),'visually_inspected':['render-rational/question-001.png','render-rational/question-003.png','render-zero-boundaries/question-001.png','render-zero-boundaries/question-002.png'],'observations':'Readable fractions, full vectors, matrices and row operations; zero coordinates and +0z explicitly visible; no clipping/overlap observed.'},'packaging':{'deterministic':p['deterministic'],'relocatable':p['relocatable'],'runtime_hashes_current':True},'inventory':{'demonstrated_historical_component_cue_records':10,'latest_fraction_cue_in_these_records':0,'affected':'affected-inventory.json','complete_records':'generated-records.json'},'commands':['bash checks/run-repair2.sh > evidence/repair2-validation.log 2>&1','python -B checks/inventory_reproduction.py','python -B checks/final_report.py'],'limitations':['Live learner history, actual future entity IDs and policy weights are unavailable; read-only selection analysis states its assumptions.','Ten historically generated inventory records were reproduced; remaining inventory is not certified unaffected.','Requested easy is validated; legacy moderate/hard difficulty is not recertified.','Finite shortcut probes support their tested claims, not the absence of every possible strategy.']}
assert read('render-rational/rendering.json')['passed'] and read('render-zero-boundaries/rendering.json')['passed']
(E/'repair2-summary.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'runtime_hashes_current':True,'affected_solution_sets':semantic,'native_acceptances':g['accepted_checks'],'native_rejections':g['rejected_checks']}))
